package org.example.insurance.policyholder; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="nominees") public class Nominee {@Id @GeneratedValue private Long id; @Column(nullable=false) private Long policyholderId; @Column(nullable=false) private String nomineeName; private String relationship; private LocalDate dob; private String contactNo; public Long getId(){return id;} public Long getPolicyholderId(){return policyholderId;} public void setPolicyholderId(Long v){policyholderId=v;} public String getNomineeName(){return nomineeName;} public void setNomineeName(String v){nomineeName=v;} public String getRelationship(){return relationship;} public void setRelationship(String v){relationship=v;} public LocalDate getDob(){return dob;} public void setDob(LocalDate v){dob=v;} public String getContactNo(){return contactNo;} public void setContactNo(String v){contactNo=v;}}
